{
  "name": "数据混合扩展",
  "name_en": "Data Mixer Extension",
  "manufacturer": "",
  "description": "这是一个用于实验测控流程的数据处理扩展，而非可明确识别的独立物理仪器。它用于汇集多个探测器的数据，按选定模型进行处理，生成计算结果或虚拟探测器信号，并用于实时快照、结果可视化和实验数据融合。",
  "description_en": "This appears to be a data-processing extension rather than a clearly identifiable standalone physical instrument. It is used in laboratory measurement workflows to combine data from multiple detectors, process them with a selected model, generate computed or virtual detector signals, and support real-time snapshots, visualization, and data fusion.",
  "tag_hints": [
    "data fusion",
    "multi-detector processing",
    "computed detectors",
    "real-time data processing",
    "experimental data visualization",
    "model-based analysis"
  ],
  "actions": [
    {
      "action_name": "auto-setup_docks",
      "description": "配置数据混合工作区的停靠面板布局。",
      "description_en": "Set up the dock layout for the data-mixing workspace."
    },
    {
      "action_name": "auto-validate_config",
      "description": "读取并校验已保存的数据混合配置。",
      "description_en": "Read and validate the saved data-mixer configuration."
    },
    {
      "action_name": "auto-setup_actions",
      "description": "创建数据混合功能所需的操作项。",
      "description_en": "Create the actions used by the data-mixing workflow."
    },
    {
      "action_name": "auto-connect_things",
      "description": "连接界面操作、信号与处理逻辑。",
      "description_en": "Connect UI actions, signals, and processing logic."
    },
    {
      "action_name": "auto-update_model_settings_from_action",
      "description": "根据所选模型更新模型参数设置。",
      "description_en": "Update model settings according to the selected model."
    },
    {
      "action_name": "auto-process_data",
      "description": "处理输入实验数据并生成混合结果。",
      "description_en": "Process incoming experimental data and generate mixed results."
    },
    {
      "action_name": "auto-snap",
      "description": "执行一次即时数据采集与计算快照。",
      "description_en": "Perform a one-shot acquisition and computation snapshot."
    },
    {
      "action_name": "auto-create_computed_detectors",
      "description": "创建计算得到的虚拟探测器通道。",
      "description_en": "Create computed virtual detector channels."
    },
    {
      "action_name": "auto-update_connect_detectors",
      "description": "更新探测器连接状态。",
      "description_en": "Update the detector connection state."
    },
    {
      "action_name": "auto-connect_detectors",
      "description": "连接或断开探测器数据流。",
      "description_en": "Connect or disconnect detector data streams."
    },
    {
      "action_name": "auto-plot_computed_results",
      "description": "绘制计算后的结果数据。",
      "description_en": "Plot the computed result data."
    },
    {
      "action_name": "auto-ini_model",
      "description": "初始化数据处理模型。",
      "description_en": "Initialize the data-processing model."
    },
    {
      "action_name": "auto-set_model",
      "description": "设置当前使用的数据处理模型。",
      "description_en": "Set the active data-processing model."
    },
    {
      "action_name": "auto-setup_menu",
      "description": "创建并配置数据混合功能菜单。",
      "description_en": "Create and configure the menu for the data-mixing functions."
    },
    {
      "action_name": "auto-value_changed",
      "description": "在参数值变化时更新相关设置或行为。",
      "description_en": "Update related settings or behavior when a parameter value changes."
    },
    {
      "action_name": "auto-quit_fun",
      "description": "关闭数据混合功能并执行退出清理。",
      "description_en": "Close the data-mixing function and perform shutdown cleanup."
    }
  ]
}

